/// A boolean the server writes as the string "true" or "false".
mod bool_string {
        use serde::{Deserialize, Deserializer, Serializer};

        pub fn serialize<S: Serializer>(value: &bool, s: S) -> Result<S::Ok, S::Error> {
                s.serialize_str(if *value { "true" } else { "false" })
            }

            pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<bool, D::Error> {
                    #[derive(Deserialize)]
                    #[serde(untagged)]
                    enum Repr {
                            Bool(bool),
                            String(String),
                        }
                        match Repr::deserialize(d)? {
                                Repr::Bool(b) => Ok(b),
                                Repr::String(s) if s == "true" => Ok(true),
                                Repr::String(s) if s == "false" => Ok(false),
                                Repr::String(s) => Err(serde::de::Error::custom(format!("expected \"true\" or \"false\", not {s:?}"))),
                            }
                        }
                }
